package net.luis.artifactory.auth;

import org.jspecify.annotations.NonNull;
import org.jspecify.annotations.Nullable;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.io.ByteArrayOutputStream;
import java.net.URLEncoder;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.SecureRandom;
import java.time.Instant;
import java.util.Locale;

/**
 * Time based one time passwords (RFC 6238) as generated by authenticator apps: HMAC-SHA1, six digits, 30 second steps.<br>
 */
public final class Totp {

	private static final String BASE32 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
	private static final int DIGITS = 6;
	private static final long PERIOD_SECONDS = 30;
	/**
	 * Codes of this many steps before and after the current one are accepted, to tolerate clock drift between server and phone.<br>
	 */
	private static final int WINDOW = 1;
	private static final SecureRandom RANDOM = new SecureRandom();

	private Totp() {}

	/**
	 * Generates a new random secret (160 bit, base32 encoded).<br>
	 */
	@NonNull
	public static String generateSecret() {
		byte[] secret = new byte[20];
		RANDOM.nextBytes(secret);
		return encodeBase32(secret);
	}

	/**
	 * Returns the {@code otpauth://} uri authenticator apps import from a qr code.<br>
	 */
	@NonNull
	public static String uri(@NonNull String issuer, @NonNull String account, @NonNull String secret) {
		String label = encode(issuer) + ":" + encode(account);
		return "otpauth://totp/" + label + "?secret=" + secret + "&issuer=" + encode(issuer) + "&algorithm=SHA1&digits=" + DIGITS + "&period=" + PERIOD_SECONDS;
	}

	public static long step(@NonNull Instant now) {
		return Math.floorDiv(now.getEpochSecond(), PERIOD_SECONDS);
	}

	/**
	 * Returns the code of the given time step.<br>
	 */
	@NonNull
	public static String code(@NonNull String secret, long step) {
		byte[] key = decodeBase32(secret);
		if (key == null) {
			throw new IllegalArgumentException("Invalid base32 secret");
		}
		try {
			Mac mac = Mac.getInstance("HmacSHA1");
			mac.init(new SecretKeySpec(key, "HmacSHA1"));
			byte[] hash = mac.doFinal(ByteBuffer.allocate(8).putLong(step).array());
			int offset = hash[hash.length - 1] & 0x0F;
			int binary = ((hash[offset] & 0x7F) << 24) | ((hash[offset + 1] & 0xFF) << 16) | ((hash[offset + 2] & 0xFF) << 8) | (hash[offset + 3] & 0xFF);
			return String.format(Locale.ROOT, "%0" + DIGITS + "d", binary % 1_000_000);
		} catch (GeneralSecurityException e) {
			throw new IllegalStateException("Failed to compute totp code", e);
		}
	}

	/**
	 * Checks a code against the steps around now.<br>
	 * A code is only accepted for a step after {@code lastStep}, so an observed code can not be replayed.<br>
	 *
	 * @param lastStep The step of the last accepted code, -1 if none was accepted yet
	 * @return The matching step, -1 if the code is wrong or was already used
	 */
	public static long verify(@NonNull String secret, @Nullable String code, @NonNull Instant now, long lastStep) {
		if (code == null) {
			return -1;
		}
		String normalized = code.replace(" ", "").strip();
		if (normalized.length() != DIGITS || !normalized.chars().allMatch(Character::isDigit)) {
			return -1;
		}
		long current = step(now);
		long match = -1;
		for (long step = current - WINDOW; step <= current + WINDOW; step++) {
			// Compare every step without an early exit, so the timing does not tell which step matched
			if (constantEquals(code(secret, step), normalized) && step > lastStep && match < 0) {
				match = step;
			}
		}
		return match;
	}

	private static boolean constantEquals(@NonNull String a, @NonNull String b) {
		return java.security.MessageDigest.isEqual(a.getBytes(StandardCharsets.US_ASCII), b.getBytes(StandardCharsets.US_ASCII));
	}

	@NonNull
	private static String encode(@NonNull String value) {
		return URLEncoder.encode(value, StandardCharsets.UTF_8).replace("+", "%20");
	}

	@NonNull
	static String encodeBase32(byte @NonNull [] data) {
		StringBuilder result = new StringBuilder();
		int buffer = 0;
		int bits = 0;
		for (byte value : data) {
			buffer = (buffer << 8) | (value & 0xFF);
			bits += 8;
			while (bits >= 5) {
				result.append(BASE32.charAt((buffer >> (bits - 5)) & 0x1F));
				bits -= 5;
			}
		}
		if (bits > 0) {
			result.append(BASE32.charAt((buffer << (5 - bits)) & 0x1F));
		}
		return result.toString();
	}

	static byte @Nullable [] decodeBase32(@NonNull String value) {
		ByteArrayOutputStream result = new ByteArrayOutputStream();
		int buffer = 0;
		int bits = 0;
		for (char c : value.toUpperCase(Locale.ROOT).toCharArray()) {
			if (c == '=' || c == ' ') {
				continue;
			}
			int index = BASE32.indexOf(c);
			if (index < 0) {
				return null;
			}
			buffer = (buffer << 5) | index;
			bits += 5;
			if (bits >= 8) {
				result.write((buffer >> (bits - 8)) & 0xFF);
				bits -= 8;
			}
		}
		return result.toByteArray();
	}
}
